package com.nivor.ai;import com.nivor.common.entity.AuditedEntity;import com.nivor.user.User;import jakarta.persistence.*;
@Entity @Table(name="ai_conversations",indexes=@Index(name="idx_ai_conversation_user",columnList="user_id,updated_at"))public class AiConversation extends AuditedEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@Column(nullable=false,length=160)private String title;protected AiConversation(){}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}}
